import{readFileSync,writeFileSync,existsSync,realpathSync,mkdirSync,copyFileSync,renameSync,constants,statSync,lstatSync}from'node:fs';
import{dirname}from'node:path';import{createHash}from'node:crypto';
const hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex'),load=p=>JSON.parse(readFileSync(p,'utf8'));
const check=(ok,why)=>{if(!ok)throw Error(why);};
const plan=load(process.argv[2]);check(hash(plan.protocol.path)===plan.protocol.sha256,'Protocoldrift');
const protocol=load(plan.protocol.path);check(hash(protocol.scripts.controller.path)===protocol.scripts.controller.sha256,'Controllerdrift');
check(!existsSync(plan.output),'Refuseexistingexecution');for(const p of Object.values(protocol.slots)){check(!existsSync(dirname(p))&&!existsSync(p),'Refuseexistingslot');mkdirSync(dirname(p));check(realpathSync(dirname(p))===dirname(p),'Slotparentalias');}
const result={schemaVersion:1,status:'RUNNING',protocol:plan.protocol,cells:[],slotStates:{}};const save=()=>writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');save();
for(const cell of plan.cells){
 const row={sequence:cell.sequence,id:cell.id,block:cell.block,slot:cell.slot,content:cell.content,status:'PREPARING',request:cell.request,immutableSource:protocol.images[cell.content],command:cell.command,cwd:cell.cwd,report:cell.report};result.cells.push(row);save();
 try{
  check(!existsSync(cell.report),'Refuseexistingreport');check(hash(cell.request.path)===cell.request.sha256,'Requestdrift');
  const request=load(cell.request.path),path=protocol.slots[cell.slot],source=protocol.images[cell.content];
  check(request.image===path&&request.pins[path]===source.sha256,'Slotrequestmismatch');check(realpathSync(source.path)===source.path&&hash(source.path)===source.sha256,'Originalimagedrift');
  const previous=result.slotStates[cell.slot]??null;row.previousSlotState=previous;
  if(previous){check(existsSync(path)&&lstatSync(path).isFile()&&!lstatSync(path).isSymbolicLink()&&realpathSync(path)===path&&hash(path)===previous.sha256,'Previousownedslotdrift');}else check(!existsSync(path),'Unexpectedinitialslot');
  const temporary=path+'.next-'+cell.sequence;check(!existsSync(temporary),'Refuseexistingtemporary');copyFileSync(source.path,temporary,constants.COPYFILE_EXCL);check(hash(temporary)===source.sha256&&statSync(temporary).size===protocol.imageBytes[cell.content],'Copydrift');renameSync(temporary,path);check(realpathSync(path)===path,'Slotnotcanonical');
  row.prepared={path,sha256:hash(path),bytes:statSync(path).size,sourceSha256:hash(source.path),requestSha256:hash(cell.request.path),preparedAt:new Date().toISOString()};check(row.prepared.sha256===source.sha256,'Preparedslothash');row.status='RUNNING';save();console.log('START '+cell.id+' '+new Date().toISOString());
  const before=performance.now(),child=Bun.spawn(cell.command,{cwd:cell.cwd,stdout:'pipe',stderr:'pipe'});const out=new Response(child.stdout).text(),err=new Response(child.stderr).text();row.exitCode=await child.exited;[row.stdout,row.stderr]=await Promise.all([out,err]);row.elapsedMs=performance.now()-before;
  check(existsSync(cell.report),'Missingactualreport');const actual=load(cell.report);row.actualReport={path:cell.report,sha256:hash(cell.report)};row.guardian=actual.guardian;row.after={path,sha256:hash(path),bytes:statSync(path).size,sourceSha256:hash(source.path),requestSha256:hash(cell.request.path),finishedAt:new Date().toISOString()};
  check(row.exitCode===0&&actual.status==='PASS'&&actual.guardian?.status==='PASS'&&actual.guardian.ownedTreeStopped===true,'Actualruntimefailure');check(actual.requestSha256===cell.request.sha256&&row.prepared.sha256===source.sha256&&row.after.sha256===source.sha256&&row.after.sourceSha256===source.sha256&&row.after.requestSha256===cell.request.sha256,'Afterrunprovenancefailed');
  row.status='PASS';row.passed=true;result.slotStates[cell.slot]={path,sha256:source.sha256,bytes:row.after.bytes,lastWriterSequence:cell.sequence,lastWriterContent:cell.content};save();console.log('FINISH '+cell.id+' PASS '+new Date().toISOString());
 }catch(error){row.status='FAILED_CELL_RETAINED';row.passed=false;row.error=String(error);row.stack=error?.stack;result.status='FAILED_CELL_RETAINED';save();console.error('FAILED '+cell.id+' '+error);process.exit(1);}
}
result.status='ALL_EIGHT_CROSSOVER_CELLS_FINISHED';save();console.log(JSON.stringify({status:result.status,cells:result.cells.length,output:plan.output,slotStates:result.slotStates}));

import{readFileSync}from'node:fs';
import{pairedStats,classifyRatio,median}from'/Users/ilyagulya/Projects/My/bend/evals/selfhost_corpus_calibration.ts';
const rows=JSON.parse(readFileSync(process.argv[2]!,'utf8')),protocol=JSON.parse(readFileSync(process.argv[3]!,'utf8')),metrics=['checkerCpuMs','checkerWallMs','footprintBytes','rssBytes'];
const cell=(block:number,slot:string,content:string)=>{const hits=rows.filter((r:any)=>r.block===block&&r.slot===slot&&r.content===content);if(hits.length!==1)throw Error('Ambiguousfactorialcell');return hits[0];};
const compare=(pairs:any[])=>{const result:any={pairs:pairs.map(p=>({baseline:p.baseline.id,variant:p.variant.id}))};for(const m of metrics){const s=pairedStats(pairs.map(p=>p.baseline[m]),pairs.map(p=>p.variant[m]));result[m]={...s,direction:classifyRatio(s.ci95,.02)};}result.medianFootprintRatio=median(pairs.map(p=>p.variant.footprintBytes))!/median(pairs.map(p=>p.baseline.footprintBytes))!;result.medianRSSRatio=median(pairs.map(p=>p.variant.rssBytes))!/median(pairs.map(p=>p.baseline.rssBytes))!;return result;};
if(rows.length!==8)throw Error('Needalloriginaleightrows');
const contentPairs=[...protocol.blocks.flatMap((b:number)=>['U','V'].map(slot=>({block:b,slot,baseline:cell(b,slot,'A'),variant:cell(b,slot,'C')})))],slotPairs=protocol.blocks.flatMap((b:number)=>['A','C'].map(content=>({block:b,content,baseline:cell(b,'U',content),variant:cell(b,'V',content)}))),orderPairs=['U','V'].flatMap(slot=>['A','C'].map(content=>({slot,content,baseline:cell(1,slot,content),variant:cell(2,slot,content)})));
const content=compare(contentPairs),url=compare(slotPairs),order=compare(orderPairs),contentBySlot=Object.fromEntries(['U','V'].map(s=>[s,compare(contentPairs.filter(p=>p.slot===s))])),urlByContent=Object.fromEntries(['A','C'].map(c=>[c,compare(slotPairs.filter(p=>p.content===c))]));
const interactions:any={};for(const m of metrics){const u=protocol.blocks.map((b:number)=>cell(b,'U','C')[m]/cell(b,'U','A')[m]),v=protocol.blocks.map((b:number)=>cell(b,'V','C')[m]/cell(b,'V','A')[m]),s=pairedStats(u,v);interactions[m]={...s,direction:classifyRatio(s.ci95,.02),definition:'(C/A at V)/(C/A at U), paired within mirrored block'};}
const limit=protocol.contentScreen,point={cpu:content.checkerCpuMs.geometricMeanRatio<=limit.geometricCPU_CA_atMost,everyCPU:contentPairs.every(p=>p.variant.checkerCpuMs/p.baseline.checkerCpuMs<limit.everyCPU_CA_below),wall:content.checkerWallMs.geometricMeanRatio<=limit.geometricWall_CA_atMost,medianFootprint:content.medianFootprintRatio<=limit.medianPhysicalFootprint_CA_atMost,cpuBothSlots:Object.values(contentBySlot).every((s:any)=>s.checkerCpuMs.geometricMeanRatio<1),footprintBothSlots:Object.values(contentBySlot).every((s:any)=>s.medianFootprintRatio<=1.02)},outside=(x:number)=>x<.98||x>1.02;
console.log(JSON.stringify({schemaVersion:1,rows,content_C_over_A:content,contentBySlot,url_V_over_U:url,urlByContent,block2_over_block1:order,interaction:interactions,contentPointScreen:point,contentPointScreenPassed:Object.values(point).every(Boolean),contentCPUUpper95Pass:content.checkerCpuMs.ci95[1]<=.98,sourceQualificationEarned:Object.values(point).every(Boolean)&&content.checkerCpuMs.ci95[1]<=.98,diagnosticTriggers:{urlCPU:outside(url.checkerCpuMs.geometricMeanRatio),urlFootprint:outside(url.medianFootprintRatio),contentURLInteractionCPU:outside(interactions.checkerCpuMs.geometricMeanRatio),contentURLInteractionFootprint:outside(interactions.footprintBytes.geometricMeanRatio),blockCPU:outside(order.checkerCpuMs.geometricMeanRatio),blockFootprint:outside(order.medianFootprintRatio)},acceptanceEvidence:false,scope:'Two mirrored full-factorial blocks,8freshprocesses. Each contrast uses4disjoint within-contrast pairs; different contrasts reuse observations and are not independent. Mirroring cancelsfirst-order linear position trend,notarbitrarycohort/thermal/nonlinearity. FixedslotsarenewURLs:notreplayofG75URLs. OriginalG73/G74/G75decisionsunchanged,notimingpooling. Passing diagnosticonlyearnsseparatelycheckpointedfull/C3sourcequalification,notproductiongain.'},null,2));
